INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(14163, 'koKR', 'Wezwanie do boju: Wyspa Podboju', 'W miarę jak zbliżamy się do zwycięstwa w Lodowej Koronie, coraz wyraźniej widać, że nasze armie będą musiały rozprawić się z Hordą, zanim zajmą się Królem Liszem.$B$BElitarna gwardia zwana Kor\'kronem została wysłana, by zablokować nasz pochód na Wyspie Podboju. Wyspa ma kluczowe znaczenie strategiczne, $N. Dopilnuj, żeby nasi chłopcy zwyciężyli!', 'Wygraj bitwę na Wyspie Podboju i wróć do generała brygady Przymierza w dowolnej stolicy Przymierza, w Zimościsku, Dalaranie lub Shattrath.', 'Zwycięstwo na Wyspie Podboju', '', '', '', '', '', 0),
(14164, 'koKR', 'Wezwanie do boju: Wyspa Podboju', 'Zwycięstwo w Północnej Grani wkrótce będzie nasze... ale nie wcześniej, niż zdobędziemy przyczółek w Lodowej Koronie, by przerzucać i zaopatrywać nasze siły.$B$BWyspa Podboju to idealne miejsce. Łatwo jej bronić i jest bogata w zasoby. Przymierze doszło do tego samego wniosku i wysłało 7. Legion, by odebrał nam nad nią kontrolę.$B$BIdź, $N, i dopilnuj, by Horda zwyciężyła za wszelką cenę!', 'Wygraj bitwę na Wyspie Podboju i wróć do zwiastuna wojny Hordy w dowolnej stolicy Hordy, w Zimościsku, Dalaranie lub Shattrath.', 'Zwycięstwo na Wyspie Podboju', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(14163, 'koKR', 'Horda nigdy nie dorówna naszym siłom, dopóki mamy po swojej stronie ludzi takich jak ty, $N.', 0),
(14164, 'koKR', 'Nic nie stanie między nami a całkowitym zwycięstwem. Za Hordę!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(14163, 'koKR', 'Dobrze cię widzieć, $n! Masz wieści z frontu?', 0),
(14164, 'koKR', 'Czy Przymierze zostało przepędzone z pola bitwy?', 0);
